void safety(const Json& j){check(j.at("newSignatures")==0&&j.at("resumeAuthorized")==false&&j.at("headProjectionPersisted")==false&&j.at("unsignedBodyConstructionQualified")==false&&j.at("runtimeStarted")==false&&j.at("productionQualified")==false,"observation cannot grant signing or runtime");}
void emit(const char* scenario,const Json& more=Json::object()){auto j=more;j["scenario"]=scenario;j["result"]="PASS";j["syntheticFixtureOnly"]=true;j["privateInputsRead"]=false;j["newTestOnlySignaturesCreated"]=test_signatures;j["runtimeDutiesAuthorized"]=false;j["newForkActivated"]=false;j["productionQualified"]=false;std::cout<<j.dump()<<std::endl;}
template<class Exception,class F>void throws_exact(F action,const char* why){bool got=false;try{action();}catch(const Exception&){got=true;}check(got,why);}
const Json& key_row(const Json& j,uint64_t index){for(const auto& row:j.at("keys"))if(!row.at("registeredIndex").is_null()&&row.at("registeredIndex").get<uint64_t>()==index)return row;throw std::runtime_error("expected synthetic key observation absent");}
